create or replace function public.newsletter_save_draft(
  p_blocks jsonb,
  p_subject text,
  p_preheader text,
  p_actor uuid,
  p_actor_kind public.actor_kind,
  p_request_id text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old public.newsletter_issues;
  v_new public.newsletter_issues;
begin
  -- Creates the single draft or replaces the open one's blocks, subject and preheader with what `queue_digest`
  -- merged. `queue_digest` passes no actor, so its audit row is a system row (G43).
  if jsonb_typeof(p_blocks) is distinct from 'array' then
    raise exception 'validation' using errcode = '22023';
  end if;
  v_old := public.newsletter_open_draft();
  update public.newsletter_issues
  set blocks = p_blocks, subject = p_subject, preheader = p_preheader
  where id = v_old.id
  returning * into v_new;
  perform public.write_audit(
    p_actor, coalesce(p_actor_kind, 'agent'), 'newsletter.build', 'newsletter_issues', v_new.id,
    jsonb_build_object(
      'id', v_old.id, 'blocks', jsonb_path_query_array(v_old.blocks, '$[*].id'), 'subject', v_old.subject,
      'preheader', v_old.preheader
    ),
    jsonb_build_object(
      'id', v_new.id, 'blocks', jsonb_path_query_array(v_new.blocks, '$[*].id'), 'subject', v_new.subject,
      'preheader', v_new.preheader
    ),
    p_request_id,
    case when p_actor is null then 'system' end
  );
  return jsonb_build_object('id', v_new.id, 'number', v_new.number);
end;
$$;

create or replace function public.newsletter_approve_issue(
  p_issue uuid,
  p_send_at timestamptz,
  p_actor uuid,
  p_actor_kind public.actor_kind,
  p_request_id text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old public.newsletter_issues;
  v_new public.newsletter_issues;
  v_data jsonb;
begin
  -- Invariant 3: only a human approves; write_audit checks the kind as stored (DB-04). Approving an approved issue
  -- reschedules it: the jobs of the previous approval are cancelled and a new pair is keyed with the new count
  -- (invariants 6 and 11).
  if false then
    raise exception 'human_only' using errcode = '42501';
  end if;
  select * into v_old from public.newsletter_issues i where i.id = p_issue for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  if v_old.status not in ('draft', 'approved') then
    raise exception 'wrong_state' using errcode = '55000';
  end if;
  if jsonb_array_length(v_old.blocks) = 0 then
    raise exception 'issue_empty' using errcode = '22023';
  end if;
  update public.newsletter_issues
  set status = 'approved',
    approved_by = p_actor,
    scheduled_for = coalesce(p_send_at, now()),
    approval_count = approval_count + 1,
    send_error = null
  where id = p_issue
  returning * into v_new;

  perform public.cancel_job(j.id, p_actor, 'newsletter_reapproved')
  from public.jobs j
  where j.idempotency_key in (
    'newsletter_send:' || p_issue || ':' || v_old.approval_count,
    'newsletter_preview:' || p_issue || ':' || v_old.approval_count
  );
  v_data := jsonb_build_object(
    'params', '{}'::jsonb,
    'data', jsonb_build_object('issue_id', p_issue, 'approval_count', v_new.approval_count)
  );
  perform public.enqueue_job(
    'newsletter_send', v_data, 'newsletter_send:' || p_issue || ':' || v_new.approval_count,
    p_run_after => v_new.scheduled_for, p_max_attempts => 12
  );
  perform public.enqueue_job(
    'newsletter_preview', v_data, 'newsletter_preview:' || p_issue || ':' || v_new.approval_count,
    p_run_after => greatest(v_new.scheduled_for - interval '24 hours', now())
  );

  perform public.write_audit(
    p_actor, p_actor_kind, 'newsletter.approve', 'newsletter_issues', p_issue,
    jsonb_build_object(
      'id', p_issue, 'status', v_old.status, 'scheduled_for', v_old.scheduled_for,
      'approval_count', v_old.approval_count
    ),
    jsonb_build_object(
      'id', p_issue, 'status', v_new.status, 'scheduled_for', v_new.scheduled_for,
      'approval_count', v_new.approval_count
    ),
    p_request_id
  );
  return to_jsonb(v_new);
end;
$$;

create or replace function public.write_audit(
  p_actor uuid,
  p_actor_kind public.actor_kind,
  p_action text,
  p_entity text,
  p_entity_id uuid,
  p_before jsonb,
  p_after jsonb,
  p_request_id text,
  p_note text default null
)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_roles public.app_role[];
  v_kinds public.actor_kind[];
  v_rule public.action_roles;
  v_pii text[];
  v_keys text[];
  v_before jsonb := p_before;
  v_after jsonb := p_after;
  v_id bigint;
begin
  -- Invariant 18, DB-04: the actor as stored, never as the caller names it. A null actor is the system.
  -- Raised inside the writing function's transaction, so its whole change rolls back.
  if p_actor is not null then
    select array_agg(r.role), array_agg(distinct r.actor_kind)
    into v_roles, v_kinds
    from public.user_roles r
    where r.user_id = p_actor and r.disabled_at is null;
    if v_roles is null then
      raise exception 'forbidden' using errcode = '42501';
    end if;
    select * into v_rule from public.action_roles a where a.action = p_action;
    if not found then
      raise exception 'forbidden' using errcode = '42501';
    end if;
    if v_rule.human_only and p_actor_kind = 'agent' then
      raise exception 'human_only' using errcode = '42501';
    end if;
    if not (v_rule.roles && v_roles) then
      raise exception 'forbidden' using errcode = '42501';
    end if;
  end if;

  -- DB-03: only the keys that changed, plus `id`, and no value of a personal-data column. The entity is the
  -- table name or its singular (`submission`, `property`, `story`); a hash is never stored, it can be reversed.
  if jsonb_typeof(coalesce(p_before, '{}')) = 'object' and jsonb_typeof(coalesce(p_after, '{}')) = 'object' then
    select coalesce(array_agg(p.column_name), '{}')
    into v_pii
    from public.pii_columns p
    where p.table_name in (p_entity, p_entity || 's', regexp_replace(p_entity, 'y$', 'ies'));
    select coalesce(array_agg(k.key), '{}')
    into v_keys
    from (
      select jsonb_object_keys(coalesce(p_before, '{}')) as key
      union
      select jsonb_object_keys(coalesce(p_after, '{}'))
    ) k
    where k.key = 'id' or (p_before -> k.key) is distinct from (p_after -> k.key);
    if p_before is not null then
      select coalesce(jsonb_object_agg(e.key, case when e.key = any (v_pii) then '{"pii": "changed"}'::jsonb else e.value end), '{}')
      into v_before
      from jsonb_each(p_before) e
      where e.key = any (v_keys);
    end if;
    if p_after is not null then
      select coalesce(jsonb_object_agg(e.key, case when e.key = any (v_pii) then '{"pii": "changed"}'::jsonb else e.value end), '{}')
      into v_after
      from jsonb_each(p_after) e
      where e.key = any (v_keys);
    end if;
  end if;

  insert into public.audit_log (actor_id, actor_kind, action, entity, entity_id, before, after, request_id, note)
  values (p_actor, p_actor_kind, p_action, p_entity, p_entity_id, v_before, v_after, p_request_id, p_note)
  returning id into v_id;
  return v_id;
end;
$$;

