  set status = 'draft', approved_by = null, approval_count = approval_count + 1
  where id = p_issue
  returning * into v_new;
  perform public.cancel_job(j.id, p_actor, 'newsletter_unapproved')
  from public.jobs j
  where j.idempotency_key in (
